def summarize_templates(apps, schema_editor):
    Version = apps.get_model('awards', 'TemplateVersion')
    for version in Version.objects.only('pk', 'canvas').iterator(chunk_size=1):
        canvas = version.canvas
        native = canvas.get('engine') == 'pptist'
        slides = canvas.get('presentation', {}).get('slides', [])
        index = canvas.get('slideIndex', 0)
        elements = slides[index].get('elements', []) if native and 0 <= index < len(slides) else canvas.get('layers', [])
        Version.objects.filter(pk=version.pk).update(summary={'engine':'pptist' if native else 'legacy','page':canvas.get('page',{'width':842,'height':595}),'element_count':len(elements)})


